ValidationRule.errorConditionFormula:
OR(
    AND(
        OR(ISCHANGED(Ready_To_Service_By__c), ISCHANGED(Ready_To_Service_Date__c)),
        NOT(ISCHANGED(Status__c))
    ),
    AND(
        OR(ISCHANGED(Serviceable_By__c), ISCHANGED(Serviceable_Date__c)),
        NOT(ISCHANGED(Status__c))
    )
)
